const sources = $('Source Text Normalizer').all().map(i => i.json);
const drafts = $input.all().map(i => i.json || {});

const TLD = '(?:com|net|org|io|ai|co|dev|app|news|tech|info|biz|me|xyz|us|uk|eu|de|fr|nl|es|it|ca|au|in|jp)';

// Safety net: the prompt forbids links, this guarantees none survive into the post.
// LinkedIn auto-links bare domains, so those go too, not just full URLs.
function stripLinks(text) {
  let s = String(text || '');

  s = s.replace(/\bhttps?:\/\/\S+/gi, '');
  s = s.replace(/\bwww\.[^\s)\]]+/gi, '');
  s = s.replace(new RegExp('\\b[a-z0-9][a-z0-9-]*(?:\\.[a-z0-9-]+)*\\.' + TLD + '\\b(?:\\/[^\\s)\\]]*)?', 'gi'), '');

  // Tidy up whatever the removals left behind
  s = s.replace(/\((?:\s*via\s*)?\s*\)/gi, '');
  s = s.replace(/[ \t]{2,}/g, ' ');
  s = s.replace(/[ \t]+([.,;:!?])/g, '$1');
  s = s.replace(/\n{3,}/g, '\n\n');

  return s.trim();
}

const out = [];
const dropped = [];

// One failed or empty draft must not take the rest of the batch down with it
drafts.forEach((d, i) => {
  const src = sources[i] || {};
  const res = d.output || {};
  const post = stripLinks(res.post);

  if (d.error || !post) {
    dropped.push(src.title || ('slot ' + (i + 1)));
    return;
  }

  out.push({ json: {
    slot: src.slot || (i + 1),
    headline: String(res.headline || src.title || '').trim(),
    post: post,
    postLength: post.length,
    title: src.title || '',
    link: src.link || '',
    publication: src.publication || '',
    pickReason: src.pickReason || '',
  } });
});

if (!out.length) {
  throw new Error('Copy Composer produced no usable posts. Dropped: ' + dropped.join(' | '));
}

return out;

const topics = $('Visual Record Builder').all().map(i => i.json);

// ClickUp's chat API has no @mention support, so the reviewer is notified by
// assigning the closing message to them. Set REVIEWER_EMAIL if two people
// share a display name, it wins over the name match.
const REVIEWER_NAME = 'Petro Bilinskyi';
const REVIEWER_EMAIL = '';

const BANNER = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━';

function resolveReviewerId() {
  let roster = null;
  try { roster = $('Workspace Roster Lookup').first().json; } catch (e) { return ''; }
  if (!roster || !Array.isArray(roster.teams)) return '';

  const wantedName = REVIEWER_NAME.toLowerCase().trim();
  const wantedEmail = REVIEWER_EMAIL.toLowerCase().trim();

  const people = [];
  for (const team of roster.teams) {
    for (const m of (team.members || [])) {
      if (m && m.user && m.user.id) people.push(m.user);
    }
  }

  if (wantedEmail) {
    const byEmail = people.find(u => String(u.email || '').toLowerCase().trim() === wantedEmail);
    if (byEmail) return String(byEmail.id);
  }

  const exact = people.find(u => String(u.username || '').toLowerCase().trim() === wantedName);
  if (exact) return String(exact.id);

  // Loose match so a middle name or odd spacing still resolves
  const parts = wantedName.split(/\s+/).filter(Boolean);
  const loose = people.find(u => {
    const uname = String(u.username || '').toLowerCase();
    return parts.length && parts.every(p => uname.includes(p));
  });
  return loose ? String(loose.id) : '';
}

const reviewerId = resolveReviewerId();

const TLD = '(?:com|net|org|io|ai|co|dev|app|news|tech|info|biz|me|xyz|us|uk|eu|de|fr|nl|es|it|ca|au|in|jp)';

// LinkedIn auto-links bare domains and cuts reach on posts carrying external
// links, so nothing linkable may survive in the body. Full URLs and bare
// domains both go. The Source line below is built separately and untouched.
function stripLinks(text) {
  let s = String(text || '');

  s = s.replace(/\bhttps?:\/\/\S+/gi, '');
  s = s.replace(/\bwww\.[^\s)\]]+/gi, '');
  s = s.replace(new RegExp('\\b[a-z0-9][a-z0-9-]*(?:\\.[a-z0-9-]+)*\\.' + TLD + '\\b(?:\\/[^\\s)\\]]*)?', 'gi'), '');

  // Tidy up whatever the removals left behind
  s = s.replace(/\((?:\s*via\s*)?\s*\)/gi, '');
  s = s.replace(/[ \t]{2,}/g, ' ');
  s = s.replace(/[ \t]+([.,;:!?])/g, '$1');
  s = s.replace(/\n{3,}/g, '\n\n');

  return s.trim();
}

const messages = topics.map((t, i) => {
  const lines = [];

  lines.push(BANNER);
  lines.push('## 📝 POST ' + (i + 1) + ' SUGGESTION');
  lines.push(BANNER);
  lines.push('');
  lines.push('**' + String(t.headline || '').trim() + '**');
  lines.push('');
  lines.push(stripLinks(t.post));
  lines.push('');
  lines.push('----');
  lines.push('');
  // Direct 1200x627 JPG, right-click and save straight from the browser
  lines.push('Link to image: ' + (t.hasVisual ? t.visualUrl : 'generation failed for this topic, pick a visual manually'));
  lines.push('Source: ' + t.link);

  return { json: {
    slot: t.slot,
    headline: t.headline,
    title: t.title,
    link: t.link,
    visualUrl: t.visualUrl || '',
    assignee: '',
    messageMarkdown: lines.join('\n'),
  } };
});

// Closing message that hands the batch over for a human decision. The assignee
// is what actually notifies them, the @name is only there so the text reads right.
messages.push({ json: {
  slot: 0,
  isReviewPrompt: true,
  headline: '',
  title: '',
  link: '',
  visualUrl: '',
  assignee: reviewerId,
  reviewerResolved: Boolean(reviewerId),
  messageMarkdown: '@' + REVIEWER_NAME + ' what do you think we should post?',
} });

return messages;

const sd = $getWorkflowStaticData('global');
const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;

const batch = $('Visual Record Builder').all().map(i => i.json);
const dispatch = $input.all().map(i => i.json || {});

let usedTopics = (sd.usedTopics || [])
  .map(t => typeof t === 'string' ? { title: t, ts: now } : t)
  .filter(t => t && t.title && (now - (t.ts || 0)) < SEVEN_DAYS);

const sent = [];
const failed = [];

// Only mark a topic as covered once ClickUp actually accepted it, so a failed
// send comes back around on the next run instead of being silently burned
batch.forEach((b, i) => {
  if (!b || !b.title) return;
  const res = dispatch[i];
  if (res && !res.error) {
    usedTopics.push({ title: b.title, ts: now });
    sent.push(b);
  } else {
    failed.push(b.title);
  }
});

sd.usedTopics = usedTopics.slice(-60);
sd.candidatePool = [];
sd.currentBatch = null;

return [{ json: {
  deliveredTopics: sent.length,
  failedTopics: failed,
  withVisual: sent.filter(b => b.hasVisual).length,
  topics: sent.map(b => ({
    headline: b.headline,
    title: b.title,
    link: b.link,
    visualUrl: b.visualUrl || null,
  })),
} }];

// One locked template. The director fills four slots with whatever it imagines,
// and everything that must never change lives here, outside the model's reach.
const TEMPLATE = '[SUBJECT] [ACTION], [SETTING]. [LIGHT].';

const STYLE = 'Photorealistic editorial photograph, shot on a full-frame camera with a 35mm lens at f/2.0. Real photography, never illustration. Shallow depth of field with a softly blurred background, natural unforced composition with the main subject placed off centre and clear negative space on one side, nothing important near the top or bottom edge so the frame survives a 1.91:1 crop. Muted natural colour grading, true to life materials and textures, no glossy retouching and no staged stock-photo look. ABSOLUTELY NO TEXT anywhere in the image: no letters, words, numbers, captions, labels, signage, logos, watermarks, brand marks, book or screen titles, phone or laptop interface text, whiteboard or notebook writing, and no written characters of any alphabet. Any screen, label, monitor, packaging or flat surface in frame must be blank, abstract or thrown out of focus. No collage, no split frames, no borders, no text overlay, no illustration, no 3D render, no CGI look, no infographic and no charts.';

const FALLBACK = {
  subject: 'a quiet modern workspace with a single empty chair',
  action: 'caught in a still, unoccupied moment',
  setting: 'in a room with large windows and softly blurred greenery outside',
  light: 'soft natural daylight, calm and neutral',
};

function tidy(value, fallback) {
  const s = String(value || '').trim().replace(/\s+/g, ' ').replace(/\.+$/, '');
  return s.length >= 3 ? s : fallback;
}

const drafts = $('Draft Packager').all().map(i => i.json);

const out = ($input.first().json.output) || {};
const scenes = Array.isArray(out.scenes) ? out.scenes : [];

const stamp = Date.now();
const claimed = new Set();

return drafts.map((d, i) => {
  // Match on the slot the director tagged, otherwise take the next unclaimed
  // scene. Each scene is consumed once so a short response can never hand two
  // posts the same picture.
  let idx = scenes.findIndex((x, k) => !claimed.has(k) && x && Number(x.slot) === Number(d.slot));
  if (idx === -1) idx = scenes.findIndex((x, k) => !claimed.has(k) && x);
  const s = idx === -1 ? {} : scenes[idx];
  if (idx !== -1) claimed.add(idx);

  const subject = tidy(s.subject, FALLBACK.subject);
  const action = tidy(s.action, FALLBACK.action);
  const setting = tidy(s.setting, FALLBACK.setting);
  const light = tidy(s.light, FALLBACK.light);

  const scene = TEMPLATE
    .split('[SUBJECT]').join(subject)
    .split('[ACTION]').join(action)
    .split('[SETTING]').join(setting)
    .split('[LIGHT]').join(light);

  return { json: {
    ...d,
    sceneSubject: subject,
    sceneAction: action,
    sceneSetting: setting,
    sceneLight: light,
    directorNote: String(s.rationale || '').trim(),
    imagePrompt: scene + ' ' + STYLE,
    objectKey: 'linkedin-' + stamp + '-' + (d.slot || (i + 1)) + '.jpg',
  } };
});

const scenes = $('Scene Prompt Forge').all().map(i => i.json);
const responses = $input.all().map(i => i.json || {});

const out = [];
const failed = [];

// Turn the base64 the image API returns into a real binary so Edit Image and
// the uploader can work with it, and re-attach the scene json the HTTP node dropped.
scenes.forEach((s, i) => {
  const res = responses[i] || {};
  const first = Array.isArray(res.data) ? res.data[0] : null;
  const b64 = first && first.b64_json;

  if (!b64) {
    failed.push(s.headline || ('slot ' + (i + 1)));
    return;
  }

  out.push({
    json: { ...s, imageGenerated: true },
    binary: {
      data: {
        data: b64,
        mimeType: 'image/jpeg',
        fileName: String(s.objectKey || 'image.jpg').split('/').pop(),
      },
    },
  });
});

if (!out.length) {
  throw new Error('The image API returned nothing usable. Failed: ' + failed.join(' | '));
}

return out;

// Cloudinary crops on delivery, so only one asset is ever stored per image.
// c_fill with g_auto keeps faces in frame, which a blind centre crop does not.
const LINKEDIN_TRANSFORM = 'c_fill,g_auto,w_1200,h_627,q_auto:good,f_jpg';

const scenes = $('Image Bytes Materializer').all().map(i => i.json);
const uploads = $input.all().map(i => i.json || {});

function linkedInUrl(secureUrl) {
  if (!secureUrl) return '';
  const marker = '/image/upload/';
  const at = secureUrl.indexOf(marker);
  if (at === -1) return secureUrl;
  return secureUrl.slice(0, at + marker.length) + LINKEDIN_TRANSFORM + '/' + secureUrl.slice(at + marker.length);
}

return scenes.map((s, i) => {
  const up = uploads[i] || {};
  const url = up.error ? '' : linkedInUrl(up.secure_url || up.url || '');

  return { json: {
    ...s,
    hasVisual: Boolean(url),
    visualUrl: url,
    visualOriginalUrl: up.secure_url || '',
    visualPublicId: up.public_id || '',
    visualSpec: '1200x627 px, 1.91:1, LinkedIn single-image post',
  } };
});

